import{z as n,x as i,o as r,c as s,q as e,j as t,D as E,d as A,s as o,S as l}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"多约束的组合","description":"","frontmatter":{"title":"多约束的组合","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dec-multi-constraint.md","filePath":"llm/dec-multi-constraint.md","lastUpdated":1791063341000}'),d={name:"llm/dec-multi-constraint.md"};function m(p,a,D,c,C,h){const B=i("Mermaid");return r(),s("div",null,[a[2]||(a[2]=e('<h1 id="多约束的组合" tabindex="-1">多约束的组合 <a class="header-anchor" href="#多约束的组合" aria-label="Permalink to &quot;多约束的组合&quot;">​</a></h1><div class="epigraph"><p>硬约束求交集，软约束做加法；交集为空时，回退顺序是产品契约，不是运行时的随机数。</p><footer>—— 据 Willard &amp; Louf, arXiv:2307.09702、XGrammar 与 n-gram 阻断（Paulus, Xiong &amp; Socher, ICLR 2018）的组合语义整理</footer></div><p><a href="/llm/dec-grammar-cache">上一课</a>让编译产物与格局掩码可复用。真实请求很少只带一条约束：工具参数要过 JSON Schema，同时禁词表要生效，同时输出不能整句照抄检索片段，同时有长度预算。本课写组合：多条约束如何并成每一步的一个合法集与一个分布，冲突怎么办、空了怎么办。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>约束按作用面分两类：<strong>支撑集操作</strong>（掩码族——文法、正则、bad words、n-gram 阻断）与<strong>打分操作</strong>（logit bias、频率惩罚、判别器能量）。支撑集操作的组合语义是交集：每条约束定义「到此为止的合法前缀集合」，组合后每步可用支撑是各集合的交。打分操作的组合语义是加法：在最终支撑内按各项之和重排。麻烦出在三处：交集可能为空（n-gram 阻断吃掉文法的唯一合法 token）；组合后的合法集可能小到把模型逼进低概率区；多条软项的先后与权重没有先验，顺序不同分布不同。缺口是组合规范：谁先谁后、空集怎么回退、每条约束的生效怎么观测。</p><p><span class="marginnote">直觉类比：支撑集操作像门卫，只管「谁能进场」——不合法的直接拦下；打分操作像评委，只给已经进场的人打分排序。门卫再多，规则也只是「同时满足所有人」；评委再多，也只是分数相加。两套规则不能混：不能让门卫按分数放人，也不能让评委给门外的人打分。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>先交硬、再加软。</strong> 每步先把所有支撑集操作按位求交（位图 AND，成本 \\(O(|\\mathcal{V}|/64)\\) 每条），得到合法集；再在合法集内施加打分操作；温度与核采样在最后。这条顺序是 <a href="/llm/logit-bias">logit bias 课</a>单请求顺序在多约束下的展开。</p><p><strong>空集回退写进契约。</strong> 交为空时按声明顺序放松：通常是软性词法约束（禁词、n-gram）先让位给结构文法——句子违法比出现重复短语严重；绝不允许静默放开文法。回退必须打点：哪条约束在第几步被放松，是验收与复盘的输入。</p><p><span class="marginnote">常见误区：初学者容易以为「多加约束总是更安全」，实际上约束叠得越多，交集越小，模型被逼到低概率区后输出的内容合法但质量明显变差——格式全对、内容胡说。判断标准不是约束条数，而是实测的「合法集平均大小」：当它缩到个位数 token，就该考虑删约束而不是加约束。</span></p><p><strong>状态并行推进。</strong> 每条硬约束维护自己的自动机状态，随采样 token 独立转移；组合不需要合并自动机——product 自动机只是理论存在，实际用「各自状态 + 每步求交」，编译与缓存按组合键（各约束键的有序元组）走。</p>',11)),(r(),t(l,null,{default:E(()=>[o(B,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22logits%20z%22%5D%20--%3E%20M1%5B%22%E6%96%87%E6%B3%95%E6%8E%A9%E7%A0%81%E7%8A%B6%E6%80%81%E6%8E%A8%E8%BF%9B%22%5D%0A%20%20Z%20--%3E%20M2%5B%22n-gram%20%2F%20bad%20words%22%5D%0A%20%20Z%20--%3E%20M3%5B%22%E6%AD%A3%E5%88%99%E6%B4%BB%E5%89%8D%E7%BC%80%22%5D%0A%20%20M1%20--%3E%20AND%5B%22%E6%94%AF%E6%92%91%E9%9B%86%E6%B1%82%E4%BA%A4%22%5D%0A%20%20M2%20--%3E%20AND%0A%20%20M3%20--%3E%20AND%0A%20%20AND%20--%3E%20E%7B%22%E7%A9%BA%E9%9B%86%3F%22%7D%0A%20%20E%20--%3E%7C%E6%98%AF%7C%20FB%5B%22%E6%8C%89%E4%BC%98%E5%85%88%E7%BA%A7%E5%9B%9E%E9%80%80%E5%B9%B6%E6%89%93%E7%82%B9%22%5D%0A%20%20E%20--%3E%7C%E5%90%A6%7C%20B%5B%22%E8%BD%AF%E9%A1%B9%E5%8A%A0%E6%B3%95%EF%BC%9Abias%20%2F%20%E6%83%A9%E7%BD%9A%22%5D%0A%20%20FB%20--%3E%20B%0A%20%20B%20--%3E%20S%5B%22%E6%B8%A9%E5%BA%A6%20%E2%86%92%20%E6%A0%B8%E9%87%87%E6%A0%B7%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>按位求交便宜的原因：位图 AND 是机器字运算，四条约束叠加也远低于一次前向的零头；真正贵的不是求交，是空集之后的人工回退与重试。交集的正确性来自各约束的语义一致：每条都定义「合法前缀」，交仍是「合法前缀」，所以组合输出仍同时满足全部硬约束。但组合改变分布质量：合法集越小，截断分布离模型先验越远，<a href="/llm/grammar-decode">文法课</a>对过紧掩码的警告在组合下被放大——「严格 JSON + 键序固定 + 禁词表」可能只剩一条骨架路径，多样本生成会塌成同一份输出。</p><p>组合键的缓存：同一组约束反复出现时，<a href="/llm/dec-grammar-cache">编译缓存</a>按元组命中；约束集合一变，各分量缓存仍有效，只有组合层的求交结果可以按步重算——它便宜，不值得缓存。</p><p><span class="marginnote">观测比求解难：给每条约束记「最后生效步」，谁把支撑集打到只剩一两个 token、谁触发了回退，一目了然。没有这张表，多约束系统退化成玄学调参。</span></p><p>第一张图画的是每步的组合顺序；空集发生时回退具体怎么走，是另一条独立路径：</p>',5)),(r(),t(l,null,{default:E(()=>[o(B,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E6%B1%82%E4%BA%A4%E7%BB%93%E6%9E%9C%E4%B8%BA%E7%A9%BA%22%5D%20--%3E%20C1%7B%22%E5%9B%9E%E9%80%80%E5%80%99%E9%80%89%201%EF%BC%9A%EF%BC%9Cbr%2F%EF%BC%9E%E6%94%BE%E6%9D%BE%20n-gram%20%E9%98%BB%E6%96%AD%3F%22%7D%0A%20%20C1%20--%3E%7C%E4%BA%A4%E9%9D%9E%E7%A9%BA%7C%20OK1%5B%22%E7%94%A8%E6%96%B0%E5%90%88%E6%B3%95%E9%9B%86%E7%BB%A7%E7%BB%AD%3Cbr%2F%3E%E6%89%93%E7%82%B9%EF%BC%9A%E5%93%AA%E6%AD%A5%E6%94%BE%E6%9D%BE%E4%BA%86%E8%B0%81%22%5D%0A%20%20C1%20--%3E%7C%E4%BB%8D%E7%A9%BA%7C%20C2%7B%22%E5%9B%9E%E9%80%80%E5%80%99%E9%80%89%202%EF%BC%9A%EF%BC%9Cbr%2F%EF%BC%9E%E6%94%BE%E5%AE%BD%E7%A6%81%E8%AF%8D%E8%A1%A8%3F%22%7D%0A%20%20C2%20--%3E%7C%E4%BA%A4%E9%9D%9E%E7%A9%BA%7C%20OK2%5B%22%E7%BB%A7%E7%BB%AD%20%2B%20%E6%89%93%E7%82%B9%22%5D%0A%20%20C2%20--%3E%7C%E4%BB%8D%E7%A9%BA%7C%20FAIL%5B%22%E7%A6%81%E6%AD%A2%E9%9D%99%E9%BB%98%E6%94%BE%E5%BC%80%E6%96%87%E6%B3%95%3Cbr%2F%3E%E6%8A%A5%E9%94%99%E6%88%96%E6%8D%A2%E9%99%8D%E7%BA%A7%E7%AD%96%E7%95%A5%22%5D%0A%20%20OK1%20--%3E%20LOG%5B%22%E5%9B%9E%E9%80%80%E8%AE%B0%E5%BD%95%E8%BF%9B%E7%9B%91%E6%8E%A7%22%5D%0A%20%20OK2%20--%3E%20LOG%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<p><span class="marginnote">数字实例：位图求交为什么便宜——词表 32000 个 token 用位图存是 32000 位 \\(= 4\\) KB；按 64 位机器字做 AND，一条约束一次约 500 次字运算。四条约束求交大约两千次运算，而模型前向一步是数十亿次浮点运算——相差六个数量级，所以「组合层不值得缓存」是有数字依据的。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不是所有组合都能硬叠：「关键词必现」与严格 JSON 的组合需要前瞻能量或事后验证，硬编成状态机会得到巨大的 product 且仍然不完备；跨字段不变量（<code>end</code> 不早于 <code>start</code>）本来就该留在生成后校验。组合条数有工程上限：合法集单调缩小，质量悬崖在前——按流量实测「合法集平均大小」比数条数可靠。回退顺序一旦公布就是兼容性契约：引擎升级改回退，等于改产品行为。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>硬约束按支撑集求交，软约束在交集内做加法；顺序是掩码 → 求交 → 空集回退 → 加法 → 温度与核。</li><li>每条硬约束独立推进状态，每步按位求交；组合键是有序元组，分量缓存各自有效。</li><li>空集回退按声明优先级，软词法让位结构文法，且必须打点。</li><li>合法集随组合单调缩小，质量悬崖与多样性塌缩要先测。</li><li>前瞻约束与跨字段不变量不进硬组合，交给能量项或事后校验。</li><li>出处：Willard &amp; Louf, arXiv:2307.09702；Dong et al., XGrammar, arXiv:2411.15100；n-gram 阻断见 Paulus, Xiong &amp; Socher, ICLR 2018。</li></ul>',5))])}const u=n(d,[["render",m]]);export{g as __pageData,u as default};
